package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchRequest struct {
	Workspace string   `json:"workspace"`
	Filters   []Filter `json:"filters"`
	OrderBy   string   `json:"order_by"`
	Limit     int      `json:"limit"`
}

type Filter struct {
	Field    string `json:"field"`
	Operator string `json:"op"`
	Value    string `json:"value"`
}

var allowedFields = map[string]bool{
	"title": true, "status": true, "priority": true,
	"assignee": true, "created_at": true, "updated_at": true,
}

var allowedOps = map[string]string{
	"eq": "=", "neq": "!=", "gt": ">", "lt": "<",
	"like": "LIKE", "in": "IN",
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", 405)
		return
	}

	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "invalid json", 400)
		return
	}

	if req.Limit <= 0 || req.Limit > 100 {
		req.Limit = 25
	}

	// Build query with workspace isolation
	query := fmt.Sprintf("SELECT id, title, status, priority, assignee, created_at FROM tickets WHERE workspace_id = '%s'", req.Workspace)

	// Apply filters with field validation
	for _, f := range req.Filters {
		if !allowedFields[f.Field] {
			http.Error(w, fmt.Sprintf("invalid field: %s", f.Field), 400)
			return
		}
		sqlOp, ok := allowedOps[f.Operator]
		if !ok {
			http.Error(w, fmt.Sprintf("invalid operator: %s", f.Operator), 400)
			return
		}
		if f.Operator == "in" {
			// IN operator: value is comma-separated list
			parts := strings.Split(f.Value, ",")
			quoted := make([]string, len(parts))
			for i, p := range parts {
				quoted[i] = fmt.Sprintf("'%s'", strings.TrimSpace(p))
			}
			query += fmt.Sprintf(" AND %s IN (%s)", f.Field, strings.Join(quoted, ","))
		} else if f.Operator == "like" {
			query += fmt.Sprintf(" AND %s LIKE '%%%s%%'", f.Field, f.Value)
		} else {
			query += fmt.Sprintf(" AND %s %s '%s'", f.Field, sqlOp, f.Value)
		}
	}

	// Order by with validation
	if req.OrderBy != "" {
		orderField := strings.TrimPrefix(req.OrderBy, "-")
		if allowedFields[orderField] {
			if strings.HasPrefix(req.OrderBy, "-") {
				query += fmt.Sprintf(" ORDER BY %s DESC", orderField)
			} else {
				query += fmt.Sprintf(" ORDER BY %s ASC", orderField)
			}
		}
	}

	query += fmt.Sprintf(" LIMIT %d", req.Limit)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("query error: %v", err)
		http.Error(w, "internal error", 500)
		return
	}
	defer rows.Close()

	var results []map[string]interface{}
	cols, _ := rows.Columns()
	for rows.Next() {
		vals := make([]interface{}, len(cols))
		ptrs := make([]interface{}, len(cols))
		for i := range vals {
			ptrs[i] = &vals[i]
		}
		rows.Scan(ptrs...)
		row := make(map[string]interface{})
		for i, col := range cols {
			row[col] = vals[i]
		}
		results = append(results, row)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func main() {
	var err error
	db, err = sql.Open("postgres", "host=db port=5432 user=ticketapp dbname=tickets sslmode=require")
	if err != nil {
		log.Fatal(err)
	}
	http.HandleFunc("/api/v1/search", searchHandler)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
